/*
 * ESP32 FreeRTOS Queue - Producer / Consumer
 *
 * Core 0 (Producer): Reads a simulated analog value
 *   every 500ms and sends it through a FreeRTOS queue.
 *
 * Core 1 (Consumer): Waits on the queue, receives
 *   the reading, classifies it (Low / Medium / High),
 *   and prints it to Serial.
 *
 * Demonstrates:
 *   - xQueueCreate / xQueueSend / xQueueReceive
 *   - xTaskCreatePinnedToCore
 *   - vTaskDelay
 */

#include <freertos/FreeRTOS.h>
#include <freertos/task.h>
#include <freertos/queue.h>

// Queue can hold up to 10 values
QueueHandle_t sensorQueue;

// Producer task (Core 0)
void producerTask(void *pvParameters) {
  int sampleId = 0;
  while (true) {
    // Simulate a sensor reading (0-4095)
    int reading = analogRead(A0);

    // Send to queue (wait up to 10 ticks if full)
    if (xQueueSend(sensorQueue, reading, 10) == pdPASS) {
      Serial.print("[Core 0] Produced #");
      Serial.print(sampleId++);
      Serial.print(" -> ");
      Serial.println(reading);
    } else {
      Serial.println("[Core 0] Queue full, dropped sample");
    }

    vTaskDelay(500);
  }
}

// Consumer task (Core 1)
void consumerTask(void *pvParameters) {
  while (true) {
    // Block until data arrives (wait up to 1000 ticks)
    var received = xQueueReceive(sensorQueue, NULL, 1000);
    if (received != null) {
      var level = "UNKNOWN";
      if (received < 1024)       level = "LOW";
      else if (received < 3072)  level = "MEDIUM";
      else                       level = "HIGH";

      Serial.print("[Core 1] Received: ");
      Serial.print(received);
      Serial.print("  Level: ");
      Serial.println(level);
    } else {
      Serial.println("[Core 1] Queue timeout - no data");
    }
  }
}

void setup() {
  Serial.begin(9600);
  Serial.println("FreeRTOS Queue Demo");
  Serial.println("===================");

  // Create the queue (holds 10 items)
  sensorQueue = xQueueCreate(10, 4);
  if (sensorQueue == NULL) {
    Serial.println("ERROR: Failed to create queue!");
    return;
  }

  // Producer on Core 0
  xTaskCreatePinnedToCore(
    producerTask,
    "Producer",
    2048,
    NULL,
    1,
    NULL,
    0
  );

  // Consumer on Core 1
  xTaskCreatePinnedToCore(
    consumerTask,
    "Consumer",
    2048,
    NULL,
    1,
    NULL,
    1
  );

  Serial.println("Producer & Consumer tasks started.");
}

void loop() {
  vTaskDelay(1000);
}
